<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Presupuestos | CampoSur</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="admin-page"><main class="admin-shell"><?php require dirname(__DIR__) . '/Views/partials/module-navigation.php'; ?><section class="module-content"><header class="admin-header"><div><p class="eyebrow">Planificación financiera</p><h1>Presupuestos</h1><p class="setup-copy">Define montos por temporada y centro de costo, y compáralos contra lo ejecutado.</p></div><a class="secondary-link" href="./">Volver al dashboard</a></header><?php if ($error): ?><div class="setup-error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if ($success): ?><div class="setup-success"><?= htmlspecialchars($success) ?></div><?php endif; ?><section class="admin-columns"><article class="admin-panel"><header class="panel-header"><h2>Nuevo presupuesto</h2><p>Planificación por período</p></header><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><label>Temporada<select name="season_id" required><?php foreach ($seasons as $season): ?><option value="<?= (int) $season['id'] ?>"><?= htmlspecialchars($season['name']) ?></option><?php endforeach; ?></select></label><label>Centro de costo<select name="cost_center_id" required><?php foreach ($centers as $center): ?><option value="<?= (int) $center['id'] ?>"><?= htmlspecialchars($center['name']) ?></option><?php endforeach; ?></select></label><label>Inicio<input type="date" name="period_start" required></label><label>Término<input type="date" name="period_end" required></label><label>Monto<input type="number" name="amount" min="0.01" step="0.01" required></label><label>Notas<input name="notes"></label><button class="primary-button" type="submit">Crear presupuesto</button></form></article><article class="admin-panel"><header class="panel-header"><h2>Control presupuestario</h2><p>Presupuesto versus ejecución</p></header><div class="table-scroll"><table class="admin-table"><thead><tr><th>Período</th><th>Centro</th><th>Presupuesto</th><th>Ejecutado</th></tr></thead><tbody><?php foreach ($budgets as $budget): ?><tr><td><b><?= htmlspecialchars($budget['season_name']) ?></b><small><?= htmlspecialchars($budget['period_start']) ?> al <?= htmlspecialchars($budget['period_end']) ?></small></td><td><?= htmlspecialchars($budget['center_name']) ?></td><td>$<?= number_format((float) $budget['amount'], 0, ',', '.') ?></td><td><b>$<?= number_format((float) $budget['actual_amount'], 0, ',', '.') ?></b></td></tr><?php endforeach; ?></tbody></table></div></article></section></section></main></body></html>
